"""The architecture description document, structured after ISO/IEC/IEEE 42010."""

from __future__ import annotations

from collections.abc import Mapping

from archdiag.ad.model import AD, ADView, Element
from archdiag.ad.validate import ExportResult

MAX_CATALOGUE_ROWS = 80
MAX_TRACE_ROWS = 400

DISCLAIMER = (
    "> **Draft work product.** Generated by archdiag from static analysis of the code and from "
    "declarations in `archdiag.toml`. It is not a certified artefact, the tool is not qualified "
    "under ISO 26262-8 §11, and every statement must be reviewed by an engineer before use."
)


def _cell(text: object) -> str:
    return " ".join(str(text).replace("|", "\\|").split())


def _catalogue(ad: AD, view: ADView) -> list[str]:
    rows = [ad.elements[i] for i in view.element_ids if i in ad.elements][:MAX_CATALOGUE_ROWS]
    if not rows:
        return []
    lines = ["| Element | Type | Technology | Paths | Description |", "|---|---|---|---|---|"]
    for element in rows:
        paths = ", ".join(f"`{p}`" for p in element.paths[:3])
        lines.append(
            f"| {_cell(element.name)} | {element.type} | "
            f"{_cell(element.properties.get('technology', ''))} | {paths} | "
            f"{_cell(element.description)} |"
        )
    return lines


def _trace_rows(ad: AD) -> list[str]:
    lines = ["| Element | Type | Evidence |", "|---|---|---|"]
    count = 0
    evidence_by_element: dict[str, list[str]] = {}
    for relation in ad.relations:
        for sample in relation.evidence:
            evidence_by_element.setdefault(relation.source, []).append(sample)
    for element in sorted(ad.elements.values(), key=lambda e: (e.type, e.name)):
        if element.type in ("layer", "system"):
            continue
        samples = list(dict.fromkeys(evidence_by_element.get(element.id, [])))[:5]
        where = (
            ", ".join(f"`{s}`" for s in samples)
            or ", ".join(f"`{p}`" for p in element.paths[:3])
            or "declared"
        )
        lines.append(f"| {_cell(element.name)} | {element.type} | {where} |")
        count += 1
        if count >= MAX_TRACE_ROWS:
            lines.append("| … | | |")
            break
    return lines


def render_document(ad: AD, results: Mapping[str, ExportResult]) -> str:
    lines = [f"# Architecture description: {ad.system_name}", "", DISCLAIMER, ""]

    lines += [
        "## 1. Identification and overview",
        "",
        "| Item | Value |",
        "|---|---|",
        f"| System | {_cell(ad.system_name)} |",
        f"| Version | `{ad.version}` |",
        f"| Generated | {ad.created_at} |",
        f"| Tool | archdiag {ad.tool_version} |",
        f"| Notations | {', '.join(sorted(results))} |",
        "",
    ]
    lines += [
        ad.overview.strip()
        if ad.overview.strip()
        else "_No written overview: run `archdiag ad` without `--no-llm` to add one._",
        "",
    ]

    viewpoints_used = {v.viewpoint_id for r in results.values() for v in r.views}
    viewpoints = [vp for vp in ad.viewpoints if vp.id in viewpoints_used]
    lines += ["## 2. Stakeholders and concerns", "", "| Stakeholder | Concerns |", "|---|---|"]
    concern_text = {c.id: c.text for c in ad.concerns}
    for stakeholder in ad.stakeholders:
        concerns = "; ".join(concern_text.get(c, c) for c in stakeholder.concern_ids)
        lines.append(f"| {_cell(stakeholder.name)} | {_cell(concerns)} |")
    lines += [
        "",
        "Concerns framed by each viewpoint:",
        "",
        "| Concern | " + " | ".join(vp.name for vp in viewpoints) + " |",
        "|---|" + "---|" * len(viewpoints),
    ]
    for concern in ad.concerns:
        marks = " | ".join("✓" if concern.id in vp.concern_ids else "" for vp in viewpoints)
        lines.append(f"| {_cell(concern.text)} | {marks} |")
    lines.append("")

    lines += ["## 3. Viewpoints", ""]
    for vp in viewpoints:
        lines += [
            f"### {vp.name} (`{vp.id}`)",
            "",
            f"- Notation: {vp.notation}",
            f"- Concerns: {', '.join(vp.concern_ids)}",
            f"- Model kinds: {', '.join(vp.model_kinds)}",
            f"- Element types: {', '.join(vp.element_types)}",
            f"- Relation types: {', '.join(vp.relation_types)}",
            f"- Correspondence rules: {', '.join(vp.correspondence_rules) or 'none'}",
            "",
        ]

    lines += ["## 4. Views", ""]
    for notation, result in results.items():
        for view in result.views:
            lines += [
                f"### {view.title}",
                "",
                f"_Viewpoint: `{view.viewpoint_id}` ({notation})._ {view.description}",
                "",
            ]
            if view.mermaid:
                lines += ["```mermaid", view.mermaid.rstrip(), "```", ""]
            if view.files:
                lines += ["Files: " + ", ".join(f"`{f}`" for f in view.files), ""]
            catalogue = _catalogue(ad, view)
            if catalogue:
                lines += catalogue + [""]
            for issue in view.issues:
                lines.append(f"- {issue}")
        extra = sorted(set(result.files) - {f for v in result.views for f in v.files})
        if extra:
            lines += [f"Other {notation} files: " + ", ".join(f"`{f}`" for f in extra), ""]

    lines += ["## 5. Correspondences", "", "| Rule | Status | Detail |", "|---|---|---|"]
    for correspondence in ad.correspondences:
        lines.append(
            f"| {_cell(correspondence.description)} | {correspondence.status} | "
            f"{_cell(correspondence.detail)} |"
        )
    lines.append("")

    lines += ["## 6. Architecture decisions", ""]
    if ad.decisions:
        lines += ["| Id | Decision | Status | Rationale | Source |", "|---|---|---|---|---|"]
        for decision in ad.decisions:
            lines.append(
                f"| {_cell(decision.id)} | {_cell(decision.title)} | {decision.status} "
                f"| {_cell(decision.rationale)} | `{decision.source}` |"
            )
    else:
        lines.append(
            "No architecture decision has been recorded. Declare `[[decisions]]` in "
            "`archdiag.toml` or add ADRs under `docs/adr/`."
        )
    lines.append("")

    lines += ["## 7. Known inconsistencies and violations", ""]
    issues = [
        f"{i.notation}: {i.severity}: {i.message}" + (f" (`{i.element}`)" if i.element else "")
        for r in results.values()
        for i in r.issues
        if i.severity != "note"
    ]
    broken = [
        f"correspondence '{c.rule_id}': {c.detail}"
        for c in ad.correspondences
        if c.status == "violated"
    ]
    everything = ad.inconsistencies + broken + issues
    lines += [f"- {_cell(item)}" for item in everything] or ["None found."]
    notes = [
        f"{i.notation}: {i.message}"
        for r in results.values()
        for i in r.issues
        if i.severity == "note"
    ]
    if notes:
        lines += ["", "Notes:", ""] + [f"- {_cell(n)}" for n in notes]
    lines.append("")

    lines += ["## 8. Appendix: traceability", ""] + _trace_rows(ad)
    return "\n".join(lines) + "\n"


def element_label(element: Element) -> str:
    return f"{element.name} ({element.type})"
